1	import { describe, it, expect } from "vitest";
2	import { spawn } from "node:child_process";
3	
4	interface CliRun {
5	  stdout: string;
6	  stderr: string;
7	  code: number;
8	}
9	
10	const runCli = (input: string): Promise<CliRun> =>
11	  new Promise((resolve, reject) => {
12	    const child = spawn("node_modules/.bin/tsx", ["src/cli.ts"]);
13	    let stdout = "";
14	    let stderr = "";
15	    child.stdout.on("data", (chunk) => (stdout += chunk));
16	    child.stderr.on("data", (chunk) => (stderr += chunk));
17	    child.on("error", reject);
18	    child.on("close", (code) => resolve({ stdout, stderr, code: code ?? 0 }));
19	    child.stdin.end(input);
20	  });
21	
22	describe("claim-office CLI", () => {
23	  it("reads a scenario from stdin and writes {results:[...]} to stdout", async () => {
24	    const { stdout, code } = await runCli(
25	      JSON.stringify({
26	        customer: { yearsWithMHPCO: 5 },
27	        steps: [
28	          {
29	            op: "quote",
30	            items: [
31	              {
32	                type: "amulet",
33	                material: "silver",
34	                enchantment: 2,
35	                cursed: false,
36	              },
37	            ],
38	          },
39	        ],
40	      }),
41	    );
42	
43	    expect(code).toBe(0);
44	    expect(JSON.parse(stdout)).toEqual({ results: [{ premium: 59 }] });
45	  });
46	  it("writes a premium result for a quote step and a payout/remainingCap result for a claim step", async () => {
47	    const { stdout, code } = await runCli(
48	      JSON.stringify({
49	        customer: { yearsWithMHPCO: 5 },
50	        steps: [
51	          {
52	            op: "quote",
53	            items: [
54	              {
55	                type: "amulet",
56	                material: "silver",
57	                enchantment: 2,
58	                cursed: false,
59	              },
60	            ],
61	          },
62	          {
63	            op: "claim",
64	            policy: 0,
65	            incident: {
66	              cause: "fire",
67	              damages: [{ itemType: "amulet", amount: 200 }],
68	            },
69	          },
70	        ],
71	      }),
72	    );
73	
74	    expect(code).toBe(0);
75	    expect(JSON.parse(stdout)).toEqual({
76	      results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }],
77	    });
78	  });
79	  it.todo("exits with a non-zero status code and writes an error to stderr for an unknown item type, writing no results to stdout");
80	  it.todo("exits with a non-zero status code and writes an error to stderr for a damage to an item not in the policy");
81	  it.todo("exits with a non-zero status code and writes an error to stderr for a negative damage amount");
82	});
