1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export interface QuoteStep {
23	  op: "quote";
24	  items: Item[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	// One row per item type the office recognises. Base premium (what it costs to
58	// insure) and insurance value (what it is insured FOR) are independent numbers,
59	// but they are known for exactly the same set of types — so they belong in one
60	// table. Keeping them apart would leave two key sets that must agree with
61	// nothing enforcing it.
62	interface ItemSpec {
63	  basePremium: number;
64	  insuranceValue: number;
65	  isComponent: boolean;
66	}
67	
68	const ITEM_SPECS = {
69	  sword: { basePremium: 100, insuranceValue: 1000, isComponent: false },
70	  amulet: { basePremium: 60, insuranceValue: 600, isComponent: false },
71	  staff: { basePremium: 80, insuranceValue: 800, isComponent: false },
72	  potion: { basePremium: 40, insuranceValue: 400, isComponent: false },
73	  rune: { basePremium: 25, insuranceValue: 250, isComponent: true },
74	  moonstone: { basePremium: 25, insuranceValue: 250, isComponent: true },
75	} as const satisfies Record<string, ItemSpec>;
76	
77	type KnownItemType = keyof typeof ITEM_SPECS;
78	
79	const isKnownItemType = (type: string): type is KnownItemType =>
80	  type in ITEM_SPECS;
81	
82	// The office insures only what its price list names. An unknown type has no
83	// premium and no insurance value, so there is nothing to quote — the whole
84	// scenario is rejected rather than priced at zero.
85	const specForItem = (item: Item): ItemSpec => {
86	  if (!isKnownItemType(item.type)) {
87	    throw new Error(`The MHPCO does not insure items of type ${item.type}`);
88	  }
89	  return ITEM_SPECS[item.type];
90	};
91	
92	const basePremiumForItem = (item: Item): number => specForItem(item).basePremium;
93	
94	const BLOCK_SIZE = 3;
95	
96	const BLOCK_BASE_PREMIUM = 60;
97	
98	const sum = (amounts: number[]): number =>
99	  amounts.reduce((total, amount) => total + amount, 0);
100	
101	// "Alike" means the same exact type, not merely the same family: two runes and
102	// a moonstone are three components but not three alike ones, so grouping them
103	// by type keeps them apart and denies them the block price.
104	const groupByType = (items: Item[]): Item[][] => {
105	  const groups = new Map<string, Item[]>();
106	  for (const item of items) {
107	    const group = groups.get(item.type);
108	    if (group) {
109	      group.push(item);
110	    } else {
111	      groups.set(item.type, [item]);
112	    }
113	  }
114	  return [...groups.values()];
115	};
116	
117	// A block is three alike COMPONENTS — the discount is offered on runes and
118	// moonstones, not on swords. It is also not carved out of a larger group: the
119	// price applies only when the group holds exactly three (7 runes cost 7 × 25,
120	// not 60 + 60 + 25). Alikeness is guaranteed by the caller, which only ever
121	// passes a single group from groupByType.
122	const isComponent = (item: Item): boolean => specForItem(item).isComponent;
123	
124	const isBlock = (group: Item[]): boolean =>
125	  group.length === BLOCK_SIZE && group.every(isComponent);
126	
127	const basePremiumForGroup = (group: Item[]): number =>
128	  isBlock(group) ? BLOCK_BASE_PREMIUM : sum(group.map(basePremiumForItem));
129	
130	const basePremiumForItems = (items: Item[]): number =>
131	  sum(groupByType(items).map(basePremiumForGroup));
132	
133	const CURSE_SURCHARGE = 0.5;
134	
135	// Every modifier is an additive percentage of its OWN base — modifiers never
136	// compound with each other. Item-scoped modifiers take the affected item's base
137	// premium as their base; policy-scoped modifiers take the policy base premium
138	// (the sum of all item base premiums). So the total is always
139	// base + Σ (rate × that modifier's base), never a product of (1 + rate) factors.
140	const modifierAmount = (rate: number, base: number): number => rate * base;
141	
142	const ENCHANTMENT_SURCHARGE = 0.3;
143	
144	const ENCHANTMENT_SURCHARGE_LEVEL = 5;
145	
146	const isCursed = (item: Item): boolean => item.cursed === true;
147	
148	const attractsEnchantmentSurcharge = (item: Item): boolean =>
149	  (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_LEVEL;
150	
151	interface ItemModifier {
152	  rate: number;
153	  appliesTo: (item: Item) => boolean;
154	}
155	
156	// Each item-scoped modifier is a row: a rate and the condition under which it
157	// applies. The predicate names the modifier, so a row needs no separate label.
158	// Adding a modifier means adding a row, not a new branch.
159	const ITEM_MODIFIERS: ItemModifier[] = [
160	  { rate: CURSE_SURCHARGE, appliesTo: isCursed },
161	  { rate: ENCHANTMENT_SURCHARGE, appliesTo: attractsEnchantmentSurcharge },
162	];
163	
164	const itemModifierRates = (item: Item): number[] =>
165	  ITEM_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).map(
166	    (modifier) => modifier.rate,
167	  );
168	
169	const LOYALTY_DISCOUNT = 0.2;
170	
171	const LOYALTY_THRESHOLD_YEARS = 2;
172	
173	const isLongStanding = (customer: Customer): boolean =>
174	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
175	
176	// Discounts are surcharges with the sign flipped: expressing one as a negative
177	// rate lets it flow through the same additive sum as every surcharge, with no
178	// separate subtraction step. Discount constants stay positive magnitudes and
179	// are negated here, at the point of use, so the direction is visible in the
180	// rate list rather than buried in a constant's sign.
181	const asDiscount = (rate: number): number => -rate;
182	
183	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
184	
185	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
186	
187	// Policy-scoped modifiers apply to the policy base premium. Unlike item
188	// modifiers they select on the customer and on the quote's position in the
189	// scenario rather than on an item.
190	//
191	// The initial-assessment surcharge applies to every quote: each item is treated
192	// as a first insurance regardless of customer history. The follow-up discount
193	// is what distinguishes a customer's later contracts.
194	const policyModifierRates = (
195	  customer: Customer,
196	  isFollowUpContract: boolean,
197	): number[] => [
198	  INITIAL_ASSESSMENT_SURCHARGE,
199	  ...(isLongStanding(customer) ? [asDiscount(LOYALTY_DISCOUNT)] : []),
200	  ...(isFollowUpContract ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT)] : []),
201	];
202	
203	const itemModifiersTotal = (items: Item[]): number =>
204	  sum(
205	    items.flatMap((item) =>
206	      itemModifierRates(item).map((rate) =>
207	        modifierAmount(rate, basePremiumForItem(item)),
208	      ),
209	    ),
210	  );
211	
212	const policyModifiersTotal = (
213	  policyBasePremium: number,
214	  customer: Customer,
215	  isFollowUpContract: boolean,
216	): number =>
217	  sum(
218	    policyModifierRates(customer, isFollowUpContract).map((rate) =>
219	      modifierAmount(rate, policyBasePremium),
220	    ),
221	  );
222	
223	// All amounts are rounded to whole G in the MHPCO's favour. Which way that
224	// points depends on which way the money flows: a premium comes in, so it rounds
225	// up; a payout goes out, so it rounds down.
226	//
227	// Two functions rather than one taking a direction, so that knowing which way
228	// favour points for a given kind of money stays here. A direction parameter
229	// would push that back onto every caller — the one thing these exist to answer.
230	const roundPremiumInMHPCOsFavour = (amount: number): number =>
231	  Math.ceil(amount);
232	
233	const roundPayoutInMHPCOsFavour = (amount: number): number =>
234	  Math.floor(amount);
235	
236	const quotePremium = (
237	  items: Item[],
238	  customer: Customer,
239	  isFollowUpContract: boolean,
240	): number => {
241	  const policyBasePremium = basePremiumForItems(items);
242	  return roundPremiumInMHPCOsFavour(
243	    policyBasePremium +
244	      itemModifiersTotal(items) +
245	      policyModifiersTotal(policyBasePremium, customer, isFollowUpContract) +
246	      PROCESSING_FEE,
247	  );
248	};
249	
250	const insuranceValueForItem = (item: Item): number =>
251	  specForItem(item).insuranceValue;
252	
253	// Deliberately NOT the shape of basePremiumForItems. Both aggregate a per-item
254	// figure from ITEM_SPECS, but the premium side groups by type first so a block
255	// of three alike components can be priced as one; this side never groups. Three
256	// runes cost 60 to insure and are insured for 3 × 250 = 750. The block is a
257	// discount on the price of cover, not a reduction of the cover bought.
258	//
259	// So the near-symmetry is a false friend: factoring the two into one traversal
260	// would read as tidier and would silently make blocks shrink the insurance sum.
261	// The repetition of `sum(items.map(...))` is the price of keeping them free to
262	// diverge, and is paid on purpose.
263	const insuranceSum = (items: Item[]): number =>
264	  sum(items.map(insuranceValueForItem));
265	
266	const CAP_MULTIPLE = 2;
267	
268	// The cap is twice the insurance sum — the value the items are insured FOR, so
269	// it is computed from the items alone and never from the premium. Curses,
270	// enchantments and loyalty change what a policy costs without changing what it
271	// covers (as do blocks — see insuranceSum). Naming the relation keeps that
272	// separation visible at the one place a policy is created.
273	const capForItems = (items: Item[]): number =>
274	  CAP_MULTIPLE * insuranceSum(items);
275	
276	const DEDUCTIBLE = 100;
277	
278	interface Policy {
279	  items: Item[];
280	  remainingCap: number;
281	}
282	
283	// Steps are not independent: a quote's premium depends on how many quotes came
284	// before it, and a claim draws down the cap of a policy an earlier quote
285	// created. So a step is a function from state to (result, next state), and the
286	// scenario is a fold over that — not a map, which would promise an independence
287	// the steps do not have.
288	//
289	// Policies are keyed by the index of the quote step that created them: a claim
290	// step names its policy by that zero-based index.
291	interface ScenarioState {
292	  // What makes a contract a follow-up is that the customer has already been
293	  // quoted in this scenario — the first quote is the initial contract, every
294	  // later one follows it. This is what decides whether the 15 % discount
295	  // applies.
296	  //
297	  // A flag rather than a count of quotes so far: the rule asks only whether a
298	  // quote has happened, never how many. A counter would carry a number nothing
299	  // reads — every value from 1 upward answers the only question asked
300	  // identically — and would invite the reader to wonder what the third quote
301	  // does differently. Nothing.
302	  hasQuotedBefore: boolean;
303	  policies: Map<number, Policy>;
304	}
305	
306	// A fresh state per run, not a shared constant. The Map makes the difference:
307	// a module-level seed would hand every scenario the same one. Nothing mutates
308	// it today — withPolicy copies before it writes — so a shared seed would work,
309	// but only by an invariant that lives in another function and would have to be
310	// rediscovered by the next writer. Building the seed per run makes each
311	// scenario's independence a property of the code rather than a promise about it.
312	const initialState = (): ScenarioState => ({
313	  hasQuotedBefore: false,
314	  policies: new Map(),
315	});
316	
317	interface StepOutcome {
318	  result: StepResult;
319	  state: ScenarioState;
320	}
321	
322	// Both operations end by filing a policy under its quote's index — a claim
323	// re-files the same policy with a drawn-down cap. Naming that once keeps the
324	// Map out of the operations, so neither has to know how policies are stored.
325	const withPolicy = (
326	  state: ScenarioState,
327	  policyIndex: number,
328	  policy: Policy,
329	): ScenarioState => ({
330	  ...state,
331	  policies: new Map(state.policies).set(policyIndex, policy),
332	});
333	
334	const runQuote = (
335	  step: QuoteStep,
336	  customer: Customer,
337	  state: ScenarioState,
338	  stepIndex: number,
339	): StepOutcome => ({
340	  result: {
341	    premium: quotePremium(step.items, customer, state.hasQuotedBefore),
342	  },
343	  state: withPolicy(
344	    { ...state, hasQuotedBefore: true },
345	    stepIndex,
346	    {
347	      items: step.items,
348	      remainingCap: capForItems(step.items),
349	    },
350	  ),
351	});
352	
353	const REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
354	
355	const REDUCED_REIMBURSEMENT_RATE = 0.5;
356	
357	const FULL_REIMBURSEMENT_RATE = 1;
358	
359	// Reads enchantment like the premium-side surcharge rule, but is a different
360	// rule with its own level: this one halves what a claim pays out, that one
361	// raises what a policy costs. Sharing a predicate would tie two levels that the
362	// spec lets move independently, so the shape is repeated deliberately.
363	const qualifiesForReducedReimbursement = (item: Item): boolean =>
364	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL;
365	
366	// The reimbursement rate is decided first, then one deductible comes off.
367	//
368	// The dragon-material clause is absent on purpose, not by oversight. It promises
369	// full reimbursement of the damage before the deductible — which is exactly what
370	// FULL_REIMBURSEMENT_RATE already gives every item that misses the reduced-rate
371	// clause. Where both clauses apply the spec awards it to the 50 % rule. Between
372	// them the two facts leave the clause with no input it can move: dragon material
373	// at enchantment 9 or 8 pays the same 400 as steel at those levels, and at
374	// enchantment 5 it pays the same 700 steel would. Writing it as its own branch
375	// would add a branch no test could ever tell from the default — a distinction
376	// the domain does not make.
377	const reimbursementRate = (item: Item): number =>
378	  qualifiesForReducedReimbursement(item)
379	    ? REDUCED_REIMBURSEMENT_RATE
380	    : FULL_REIMBURSEMENT_RATE;
381	
382	const payoutForDamage = (damage: Damage, item: Item): number =>
383	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
384	
385	// Returns AN insured item of the damaged type, not THE damaged one — a policy
386	// can cover two swords, so the type does not name a unique item. Two damage
387	// entries of the same type are both answered with the same first match.
388	//
389	// That is sound today because the answer is used solely to read payout
390	// attributes (the reimbursement rate), and the covered case — two damages
391	// against two swords — insures identical swords, which read the same either
392	// way. The deductible is charged per damage entry, not per matched item, so
393	// counting is unaffected too.
394	//
395	// One thing would break it, not yet under test: two swords with DIFFERENT
396	// attributes (say enchantment 3 and 9). Both damages would take the first
397	// sword's rate; the second should take its own. This lookup must then become a
398	// pairing that consumes what it matches. The honest name marks that spot.
399	//
400	// The `!` is a proof, not an assumption: rejectUnmatchedDamages runs first and
401	// throws unless every claimed type is covered at least as many times as it is
402	// named — so by the time this runs, a match exists for every damage entry. Both
403	// ways it could fail are covered by tests: claiming a type more often than it is
404	// insured, and claiming a type the policy does not cover at all.
405	const anInsuredItemOfDamagedType = (policy: Policy, damage: Damage): Item =>
406	  policy.items.find((item) => item.type === damage.itemType)!;
407	
408	// Counts how many times each value occurs. Deliberately typed on strings rather
409	// than on Item: the guard below tallies two different things (item types held
410	// and item types named by damages) and only their counts are ever compared, so
411	// the tally has no business knowing what the strings mean.
412	const tally = (values: string[]): Map<string, number> => {
413	  const counts = new Map<string, number>();
414	  for (const value of values) {
415	    counts.set(value, (counts.get(value) ?? 0) + 1);
416	  }
417	  return counts;
418	};
419	
420	// Every damage entry must claim an insured item of its own, so a type cannot be
421	// damaged more times than the policy covers it. One rule, three error cases the
422	// spec states separately — all of them the same comparison at different counts:
423	//
424	//   claimed > insured, insured ≥ 1  a type damaged more often than it is insured
425	//   claimed > insured, insured = 0  a type the policy does not cover at all
426	//   claimed > insured, insured = 0  a type the office does not insure at all
427	//
428	// The last two differ only in why the count is zero, which is why neither needs
429	// its own test. An uninsured type and an unknown type are both covered 0 times
430	// against a claimed 1. In particular the unknown type never reaches a lookup in
431	// ITEM_SPECS: a broomstick is not in THIS policy, which is the more precise
432	// complaint than whether the office insures broomsticks in general. The quote
433	// path is where the price list is consulted and where an unknown type is
434	// rejected as uninsurable.
435	//
436	// Checked before any payout is computed: the spec rejects the whole claim, not
437	// just the surplus entries.
438	const rejectUnmatchedDamages = (policy: Policy, incident: Incident): void => {
439	  const insured = tally(policy.items.map((item) => item.type));
440	  const claimed = tally(incident.damages.map((damage) => damage.itemType));
441	  for (const [type, claimedCount] of claimed) {
442	    const insuredCount = insured.get(type) ?? 0;
443	    if (claimedCount > insuredCount) {
444	      throw new Error(
445	        `Policy covers ${insuredCount} ${type}(s) but the claim names ${claimedCount}`,
446	      );
447	    }
448	  }
449	};
450	
451	// A damage is what an incident cost the owner, so it cannot be negative. Zero
452	// is left alone: the spec forbids only negative amounts, and a zero damage
453	// simply pays nothing once the deductible bites.
454	const isNegative = (damage: Damage): boolean => damage.amount < 0;
455	
456	const rejectNegativeDamages = (incident: Incident): void => {
457	  const negative = incident.damages.find(isNegative);
458	  if (negative) {
459	    throw new Error(
460	      `Damage to ${negative.itemType} is negative: ${negative.amount}`,
461	    );
462	  }
463	};
464	
465	// Both guards run before any payout is computed: the spec rejects the whole
466	// claim, not just the offending entries, so a valid entry alongside an invalid
467	// one must not be paid.
468	//
469	// They are two statements rather than a list of validations. Their signatures
470	// differ (only the first needs the policy), so a uniform list could hold them
471	// only by giving the second a parameter it ignores. And the order is not
472	// incidental: rejectUnmatchedDamages must come first because it is what makes
473	// the lookup in anInsuredItemOfDamagedType total — an obligation that reads as
474	// a sequenced line here but would vanish into array order in a list.
475	//
476	// Two is the whole set, not a stage on the way to more. The spec's remaining
477	// claim-side error — a damage naming an item type the office does not insure —
478	// needs no guard of its own: rejectUnmatchedDamages already catches it, because
479	// a type the office does not insure cannot be in the policy either and so is
480	// covered zero times. See its comment for why that is the more precise
481	// diagnosis rather than a lucky accident.
482	const payoutForIncident = (policy: Policy, incident: Incident): number => {
483	  rejectUnmatchedDamages(policy, incident);
484	  rejectNegativeDamages(incident);
485	  return sum(
486	    incident.damages.map((damage) =>
487	      payoutForDamage(damage, anInsuredItemOfDamagedType(policy, damage)),
488	    ),
489	  );
490	};
491	
492	// The damage decides what a claim is WORTH; the cap decides what there is left
493	// to pay it WITH. Once the cap is spent the office pays what remains, not what
494	// was asked — so the cap bounds the payout before it is charged against it.
495	//
496	// This is the guarantee that makes drawDownCap's subtraction safe: a payout that
497	// has passed through here can never exceed the balance, so the balance can never
498	// go negative. The two are a pair — bound, then spend — and neither is sound
499	// without the other.
500	const payoutWithinCap = (payout: number, remainingCap: number): number =>
501	  Math.min(payout, remainingCap);
502	
503	// A policy's cap is a balance, not a per-claim limit: each claim spends part of
504	// it and the rest carries forward to the next claim against the same policy.
505	// The balance stays non-negative because payoutWithinCap has already bounded
506	// what is spent — this subtraction does not defend itself, it relies on that.
507	//
508	// Naming the draw-down separates what the cap DOES from how a claim is assembled
509	// — the one line in runClaim that was arithmetic rather than plumbing.
510	const drawDownCap = (remainingCap: number, payout: number): number =>
511	  remainingCap - payout;
512	
513	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
514	  // A claim naming a policy that does not exist is a spec error case, but no
515	  // test drives it yet. The assertion stands in until one does — at which point
516	  // the missing case becomes the error branch rather than a crash.
517	  const policy = state.policies.get(step.policy)!;
518	  // Rounded before the clamp so the cap is only ever compared with, and reduced
519	  // by, whole G — a fractional payout would otherwise leave a fractional cap
520	  // behind for the next claim.
521	  const claimWorth = roundPayoutInMHPCOsFavour(
522	    payoutForIncident(policy, step.incident),
523	  );
524	  const payout = payoutWithinCap(claimWorth, policy.remainingCap);
525	  const remainingCap = drawDownCap(policy.remainingCap, payout);
526	  return {
527	    result: { payout, remainingCap },
528	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
529	  };
530	};
531	
532	// Dispatch decides once what a step is; each operation then owns both its
533	// result and how it advances the state, so no caller has to re-test step.op to
534	// know what the step did.
535	const runStep = (
536	  step: Step,
537	  customer: Customer,
538	  state: ScenarioState,
539	  stepIndex: number,
540	): StepOutcome =>
541	  step.op === "quote"
542	    ? runQuote(step, customer, state, stepIndex)
543	    : runClaim(step, state);
544	
545	// The fold carries both halves of the outcome: the results accumulated so far
546	// and the state the next step will see. Threading the state explicitly (rather
547	// than recovering it from the last result) keeps the dependency between steps
548	// visible in the type.
549	interface ScenarioRun {
550	  results: StepResult[];
551	  state: ScenarioState;
552	}
553	
554	const initialRun = (): ScenarioRun => ({ results: [], state: initialState() });
555	
556	// Appends the step's RESULT, not the step: `steps` is the fold's input and is
557	// never added to. Naming the accumulated list is what makes the one-result-per-
558	// step guarantee readable here — results grow by exactly one per step, in step
559	// order, because this is the only thing that grows them.
560	const appendStepResult =
561	  (customer: Customer) =>
562	  (run: ScenarioRun, step: Step, stepIndex: number): ScenarioRun => {
563	    const outcome = runStep(step, customer, run.state, stepIndex);
564	    return {
565	      results: [...run.results, outcome.result],
566	      state: outcome.state,
567	    };
568	  };
569	
570	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
571	  results: steps.reduce(appendStepResult(customer), initialRun()).results,
572	});
573

